import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Remote Replication in MicroCeph- RBD and Beyond - Utkarsh Bhatt, Canonical","description":"","frontmatter":{"title":"Remote Replication in MicroCeph- RBD and Beyond - Utkarsh Bhatt, Canonical","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["MicroCeph","RBD","Remote Replication","Ceph","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Remote_Replication_in_MicroCeph_-_RBD_and_Beyond_-_Utkarsh_Bhatt_Canonical.md","filePath":"posts/2025/Remote_Replication_in_MicroCeph_-_RBD_and_Beyond_-_Utkarsh_Bhatt_Canonical.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Remote_Replication_in_MicroCeph_-_RBD_and_Beyond_-_Utkarsh_Bhatt_Canonical.md"};function n(l,a,h,s,_,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要-microceph-中-rbd-远程复制功能的介绍与应用" tabindex="-1">会议纪要：MicroCeph 中 RBD 远程复制功能的介绍与应用 <a class="header-anchor" href="#会议纪要-microceph-中-rbd-远程复制功能的介绍与应用" aria-label="Permalink to &quot;会议纪要：MicroCeph 中 RBD 远程复制功能的介绍与应用&quot;">​</a></h3><p><strong>会议时间</strong>：2023年12月4日<br><strong>主讲人</strong>：Utkarsh Bhatt (Canonical)<br><strong>主题</strong>：MicroCeph 中的 RBD 镜像远程复制功能</p><h4 id="_1-会议背景与目标" tabindex="-1">1. <strong>会议背景与目标</strong> <a class="header-anchor" href="#_1-会议背景与目标" aria-label="Permalink to &quot;1. **会议背景与目标**&quot;">​</a></h4><ul><li><strong>MicroCeph</strong> 是 Canonical 推出的一款简化版 Ceph 管理工具，旨在降低 Ceph 的使用门槛。</li><li>会议重点介绍了 RBD 镜像远程复制功能，并计划将此功能扩展到 RADOS Gateway (RGW) 和 CephFS。</li></ul><h4 id="_2-主讲人介绍" tabindex="-1">2. <strong>主讲人介绍</strong> <a class="header-anchor" href="#_2-主讲人介绍" aria-label="Permalink to &quot;2. **主讲人介绍**&quot;">​</a></h4><ul><li>Utkarsh Bhatt 曾在华为从事专有存储产品开发，后转向开源存储领域，尤其专注于 Ceph。</li><li>他对 Ceph 的复杂性和强大功能有深入理解，并致力于通过 MicroCeph 简化 Ceph 的使用。</li></ul><h4 id="_3-microceph-的哲学" tabindex="-1">3. <strong>MicroCeph 的哲学</strong> <a class="header-anchor" href="#_3-microceph-的哲学" aria-label="Permalink to &quot;3. **MicroCeph 的哲学**&quot;">​</a></h4><ul><li>MicroCeph 的目标是让 Ceph 的使用变得更加简单，即使是对存储或 Ceph 不熟悉的用户也能轻松上手。</li><li>MicroCeph 并非 Ceph 的简化版或缩减版，而是通过智能化的默认配置和简化的操作流程，帮助用户快速部署和管理 Ceph 集群。</li><li>用户可以根据需求进行高级配置，MicroCeph 提供了灵活的参数调整选项。</li></ul><h4 id="_4-rbd-远程复制功能" tabindex="-1">4. <strong>RBD 远程复制功能</strong> <a class="header-anchor" href="#_4-rbd-远程复制功能" aria-label="Permalink to &quot;4. **RBD 远程复制功能**&quot;">​</a></h4><ul><li><strong>RBD 镜像远程复制</strong>是 Ceph 中用于将 RBD 镜像数据复制到另一个 Ceph 集群的功能，适用于备份、灾难恢复等场景。</li><li>复制模式支持 <strong>池模式</strong>（整个池的镜像复制）和 <strong>镜像模式</strong>（单个镜像的复制），并且可以选择 <strong>日志模式</strong> 或 <strong>快照模式</strong>。</li><li>复制的实现依赖于 <strong>RBD 镜像守护进程 (RBD Mirror Daemon)</strong>，用户可以在启用复制前后启动该守护进程。</li></ul><h4 id="_5-演示环节" tabindex="-1">5. <strong>演示环节</strong> <a class="header-anchor" href="#_5-演示环节" aria-label="Permalink to &quot;5. **演示环节**&quot;">​</a></h4><ul><li>演示了如何配置集群间的远程连接、启用复制、查看复制状态、故障切换、恢复同步以及禁用复制等操作。</li><li>使用两个虚拟集群进行演示，展示了 RBD 镜像远程复制功能的实际操作。</li></ul><h4 id="_6-未来计划" tabindex="-1">6. <strong>未来计划</strong> <a class="header-anchor" href="#_6-未来计划" aria-label="Permalink to &quot;6. **未来计划**&quot;">​</a></h4><ul><li>计划扩展远程复制功能到 <strong>RADOS Gateway (RGW)</strong> 和 <strong>CephFS</strong>。</li><li>将引入 <strong>多站点复制</strong>，MicroCeph 将自动处理 Realms 和 Zone Groups 的配置。</li><li>未来还将增加 <strong>监控和告警</strong> 功能，帮助运维人员实时了解复制状态。</li></ul><h4 id="_7-q-a-环节" tabindex="-1">7. <strong>Q&amp;A 环节</strong> <a class="header-anchor" href="#_7-q-a-环节" aria-label="Permalink to &quot;7. **Q&amp;A 环节**&quot;">​</a></h4><ul><li>回答了关于 MicroCeph 目标用户的问题，指出 MicroCeph 旨在让非专业用户也能轻松使用 Ceph。</li></ul><h4 id="_8-后续行动计划" tabindex="-1">8. <strong>后续行动计划</strong> <a class="header-anchor" href="#_8-后续行动计划" aria-label="Permalink to &quot;8. **后续行动计划**&quot;">​</a></h4><ul><li>继续开发和完善 MicroCeph 的远程复制功能，尤其是扩展到 RGW 和 CephFS。</li><li>增加监控和告警功能，提升运维人员的操作体验。</li><li>欢迎社区贡献者参与 MicroCeph 的开发，Canonical 提供了开源项目支持。</li></ul>',18)])])}const C=e(i,[["render",n]]);export{d as __pageData,C as default};
